#include<bits/stdc++.h>
using namespace std;
const int mod=1000000007;
inline int add(int a,int b)
{
	if((a+=b)>=mod)a-=mod;
	return a;
}
inline int mult(int a,int b)
{
	long long t=1ll*a*b;
	if(t>=mod)t%=mod;
	return t;
}
namespace matrix
{
	template<int N,int M>
	class matr
	{
		public:
			int dat[N][M];
			void init()
			{
				memset(dat,0,sizeof(dat));
			}
			void iden()
			{
				init();
				for(int i=0; i<min(N,M); i++)dat[i][i]=1;
			}
			matr<M,N> trans()
			{
				matr<M,N> out;
				for(int i=0; i<M; i++)
					for(int j=0; j<N; j++)out[i][j]=dat[j][i];
			}
			const int* operator [](const int &x)const
			{
				return dat[x];
			}
			int* operator [](const int &x)
			{
				return dat[x];
			}
			matr<N,M> operator +(const matr<N,M> a)
			{
				matr<N,M> out;
				for(int i=0; i<N; i++)
					for(int j=0; j<M; j++)out[i][j]=add(dat[i][j],a[i][j]);
				return out;
			}
			matr<N,M> operator *(const int &x)
			{
				matr<N,M> out=*this;
				for(int i=0; i<N; i++)
					for(int j=0; j<M; j++)out[i][j]=mult(out[i][j],x);
				return out;
			}
			template<int X>
			friend matr<N,M> operator *(const matr<N,X> a,const matr<X,M> b)
			{
				matr<N,M> out;
				out.init();
				for(int i=0; i<N; i++)
				{
					for(int j=0; j<X; j++)
					{
						if(a[i][j])
						{
							for(int k=0; k<M; k++)
								out[i][k]=add(out[i][k],mult(a[i][j],b[j][k]));
						}
					}
				}
				return out;
			}
	};
};
using namespace matrix;
typedef long long ll;
ll n;
int K;
vector<int> digit;
matr<35,35> A[65][35],S[65][35],P[65][35],ans;
int main()
{
	scanf("%lld%d",&n,&K);
	for(int i=0;i<K;i++)
	{
		A[0][i].iden();
		for(int j=0;j<=K;j++)A[0][i][i][j]=1;
	}
	ll len=K;
	for(int i=1;len<=n;i++,len*=K)
	{
		S[i-1][K-1]=A[i-1][K-1];
		for(int j=K-2;j>=0;j--) S[i-1][j]=A[i-1][j]*S[i-1][j+1];
        P[i-1][0]=A[i-1][0];
        for(int j=1;j<K;j++)P[i-1][j]=P[i-1][j-1]*A[i-1][j];
        A[i][0]=S[i-1][0];
        for(int j=1;j<K;j++)A[i][j]=S[i-1][j]*P[i-1][j-1];
	}
	while(n)
	{
        digit.push_back(n%K);
        n/=K;
    }
    int s=0;
    ans.iden();
    for(int i=digit.size()-1;i>=0;i--)
	{
        for(int j=0;j<digit[i];j++)
            ans=ans*A[i][(j+s)%K];
        s=(s+digit[i])%K;
    }
	int res=1;
	for(int i=0;i<K;i++)res=add(res,ans[i][K]);
	printf("%d\n",res);
	return 0;
}
